cypress_script:
describe('Challenging DOM Action Buttons', () => {
  it('should click on action buttons successfully', () => {
    cy.visit('https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a.button').contains('baz').should('be.visible').click();
    cy.get('a.button.alert').contains('bar').should('be.visible').click();
    cy.get('a.button.success').contains('qux').should('be.visible').click();
  });
  it('should not change URL on clicking edit or delete', () => {
    cy.visit('https://the-internet.herokuapp.com/challenging_dom');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a').contains('edit').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a').contains('delete').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/challenging_dom');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Challenging DOM Action Buttons', () => {
  test('should click on action buttons successfully', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/challenging_dom');
    await expect(page.locator('a.button').withText('baz')).toBeVisible();
    await page.locator('a.button').withText('baz').click();
    await expect(page.locator('a.button.alert').withText('bar')).toBeVisible();
    await page.locator('a.button.alert').withText('bar').click();
    await expect(page.locator('a.button.success').withText('qux')).toBeVisible();
    await page.locator('a.button.success').withText('qux').click();
  });
  test('should not change URL on clicking edit or delete', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/challenging_dom');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/challenging_dom');
    await page.locator('a').withText('edit').click();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/challenging_dom');
    await page.locator('a').withText('delete').click();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/challenging_dom');
  });
});
